import{_ as l}from"./chunks/comfyui_2026-07-13_093918_022.CsEPa01x.js";import{_ as e}from"./chunks/comfyui_2026-08-11_122131_553.CWaR1qxS.js";import{_ as o,o as i,c as t,at as n}from"./chunks/framework.CY22Hent.js";const s="/assets/comfyui_2026-08-24_100709_962.CM03HK-t.png",p="/assets/comfyui_2026-08-24_101314_885.BtlxM2r-.png",r="/assets/comfyui_2026-08-24_094652_746.tLi3XeJY.png",_="/assets/comfyui_2026-08-24_095821_021.DlZYxsn1.png",c="/assets/comfyui_2026-08-11_101939_553.DIFxMcD4.png",u="/assets/comfyui_2026-08-11_103619_221.QxE0KdS-.png",d="/assets/comfyui_2026-08-11_104436_914.D1ICpOOd.png",m="/assets/comfyui_2026-08-11_122345_695.CcpZNa4Q.png",h="/assets/comfyui_2026-08-12_155808_494.BCTJqwLu.png",g="/assets/comfyui_2026-08-12_162234_612.B61_7_Um.png",f="/assets/comfyui_2026-08-12_163431_997.DwrcdQFu.png",q="/assets/comfyui_2026-08-14_111934_258.hB0XY3FC.png",b="/assets/comfyui_2026-08-24_103422_254.CL36qGLW.png",y="/assets/comfyui_2026-08-24_103742_057.GZVpfOgy.png",k="/assets/comfyui_2026-08-13_173256_832.BuJq_m09.png",w="/assets/comfyui_2026-08-14_173308_170.CRsx0qsA.png",x="/assets/comfyui_2026-08-15_161553_927.Ctx_PE2w.png",C="/assets/comfyui_2026-08-15_173510_459.BkKOsMOP.png",I="/assets/comfyui_2026-08-15_222156_201.C9H6ghbW.png",P="/assets/comfyui_2026-08-15_232628_203.uRS2RIa1.png",L="/assets/comfyui_2026-08-16_001720_875.CgYOqvwt.png",v="/assets/comfyui_2026-08-16_001115_341.Dqz0BqGy.png",N=JSON.parse('{"title":"ComfyUI笔记3","description":"","frontmatter":{"title":"ComfyUI笔记3","date":"2026-08-06T00:00:00.000Z","lastUpdated":"2026-08-08T00:00:00.000Z","categories":["AI"],"tags":["ComfyUI","AI","工作流"]},"headers":[],"relativePath":"blogs/ComfyUI/ComfyUI笔记3.md","filePath":"blogs/ComfyUI/ComfyUI笔记3.md"}'),A={name:"blogs/ComfyUI/ComfyUI笔记3.md"};function E(z,a,Q,U,V,R){return i(),t("div",null,[...a[0]||(a[0]=[n('<p>[toc]</p><h1 id="comfyui笔记3" tabindex="-1">ComfyUI笔记3 <a class="header-anchor" href="#comfyui笔记3" aria-label="Permalink to &quot;ComfyUI笔记3&quot;">​</a></h1><p><img src="'+l+'" alt="comfyui_2026-07-13_093918_022.png" loading="lazy"></p><p>下面就介绍一些常用的，高级的工作流。这些工作流更复杂，但是功能更强大。也常常用于生产环境。</p><p>我的当前显卡设备是 NVIDIA RTX 5060TI 16GB。</p><h2 id="图像拼接-合成图像-工作流" tabindex="-1">图像拼接（合成图像）工作流 <a class="header-anchor" href="#图像拼接-合成图像-工作流" aria-label="Permalink to &quot;图像拼接（合成图像）工作流&quot;">​</a></h2><p>图像拼接（合成图像）工作流的主要功能就是将多个图像拼接（合成）为一个图像。</p><h3 id="合成图像-遮罩-节点" tabindex="-1">合成图像（遮罩）节点 <a class="header-anchor" href="#合成图像-遮罩-节点" aria-label="Permalink to &quot;合成图像（遮罩）节点&quot;">​</a></h3><p><img src="'+s+'" alt="comfyui_2026-08-24_100709_962.png" loading="lazy"></p><p>该节点是ComfyUI官方节点。用于将多个图像拼接（合成）为一个图像。支持将源图像叠加到目标图像的指定坐标位置，并可选择调整大小和遮罩。</p><blockquote><p>参数</p></blockquote><ul><li>目标图像：源图像将被合成到此图像上。它作为背景。</li><li>来源图像：要合成到目标图像上的源图像。此图像可选择调整大小以匹配目标图像的尺寸。</li><li>x：源图像左上角在目标图像中的 x 坐标。</li><li>y：源图像左上角在目标图像中的 y 坐标。</li><li>缩放来源图像：指示是否应将源图像调整为与目标图像尺寸匹配。</li><li>遮罩：可选参数，用于指定源图像的哪些部分应合成到目标图像上。这允许更复杂的合成操作，例如混合或部分叠加。</li></ul><h3 id="示例工作流" tabindex="-1">示例工作流 <a class="header-anchor" href="#示例工作流" aria-label="Permalink to &quot;示例工作流&quot;">​</a></h3><p><img src="'+p+'" alt="comfyui_2026-08-24_101314_885.png" loading="lazy"></p><p>该示例工作流中先将原图进行缩放和裁剪，再将处理后的原图像叠加到目标图像的指定坐标位置。最后生成一个合成后的图像。</p><h2 id="文字覆盖-文字添加-工作流" tabindex="-1">文字覆盖（文字添加）工作流 <a class="header-anchor" href="#文字覆盖-文字添加-工作流" aria-label="Permalink to &quot;文字覆盖（文字添加）工作流&quot;">​</a></h2><p>当我们想要实现在一个图片上添加文字时，我们可以使用文字覆盖工作流。</p><p>想要实现这个文字覆盖效果，目前comfyUI官方节点效果不太好。因此目前推荐按照第三方节点包来实现这个功能。</p><h3 id="第三方节点包-comfyui-comfyroll-customnodes" tabindex="-1">第三方节点包 ComfyUI_Comfyroll_CustomNodes <a class="header-anchor" href="#第三方节点包-comfyui-comfyroll-customnodes" aria-label="Permalink to &quot;第三方节点包 ComfyUI_Comfyroll_CustomNodes&quot;">​</a></h3><blockquote><p>介绍</p></blockquote><p>推荐使用第三方节点包：ComfyUI_Comfyroll_CustomNodes。该节点包中有一个 Text Overlay（文字覆盖）节点。</p><p><a href="https://github.com/Suzie1/ComfyUI_Comfyroll_CustomNodes" target="_blank" rel="noreferrer">ComfyUI_Comfyroll_CustomNodes 节点包链接地址 https://github.com/Suzie1/ComfyUI_Comfyroll_CustomNodes</a></p><p>该节点包中的文字覆盖节点相比其他文字覆盖节点，最大优势是可以直接输入原图，并且能直接在原图上写字，一步到位，不用额外节点。</p><blockquote><p>安装</p></blockquote><p>安装方式参考ComfyUI笔记。</p><h3 id="cr-overlay-text-节点" tabindex="-1">CR Overlay Text 节点 <a class="header-anchor" href="#cr-overlay-text-节点" aria-label="Permalink to &quot;CR Overlay Text 节点&quot;">​</a></h3><p>CR Overlay Text 节点是 ComfyUI_Comfyroll_CustomNodes 节点包中的一个节点。</p><p>该节点能直接在原图上写字，一步到位，不用额外节点。</p><p><img src="'+r+'" alt="comfyui_2026-08-24_094652_746.png" loading="lazy"></p><blockquote><p>参数</p></blockquote><ul><li>image：输入的图像。</li><li>文本框：你需要输入的文字。</li><li>font_name：要使用的字体文件名字。</li><li>align：文字对齐方式。垂直对齐</li><li>justify：文字对齐方式。水平对齐</li><li>margin：文字与图像的间距。一般填 0</li><li>line_spacing：行间距，多行文字才生效，单行文字填 0 即可</li><li>position_x: 文字左上角 X 坐标（水平），0 = 图片最左边</li><li>position_y: 文字左上角 Y 坐标（垂直），0 = 图片最顶端</li><li>rotation_angle: 文字旋转角度</li><li>rotation_options: 旋转的中心点</li><li>font_color_hex: 字体颜色十六进制代码，（注意节点不带 #号，直接填<code>503e23</code>）</li></ul><h3 id="示例工作流-1" tabindex="-1">示例工作流 <a class="header-anchor" href="#示例工作流-1" aria-label="Permalink to &quot;示例工作流&quot;">​</a></h3><p><img src="'+_+'" alt="comfyui_2026-08-24_095821_021.png" loading="lazy"></p><p>该示例工作流中，使用了CR Overlay Text 节点。在原图上实现文字覆盖效果。</p><h2 id="qwen-image-文生图工作流" tabindex="-1">Qwen-Image 文生图工作流 <a class="header-anchor" href="#qwen-image-文生图工作流" aria-label="Permalink to &quot;Qwen-Image 文生图工作流&quot;">​</a></h2><h3 id="模型介绍" tabindex="-1">模型介绍 <a class="header-anchor" href="#模型介绍" aria-label="Permalink to &quot;模型介绍&quot;">​</a></h3><p>Qwen-Image 是阿里通义实验室开源的 20B 级 MMDiT 架构原生高清文生图大模型，<strong>FP8 是官方推荐的平衡画质、显存、速度的量化版本</strong>，区别于原版 BF16 大显存版本。</p><p>Qwen-Image 模型的最佳图像分辨率是1328x1328。</p><blockquote><p>核心优势</p></blockquote><ol><li><strong>中文语义超强理解</strong>：原生海量中文图文训练，无需强制英文提示词，国风、中式场景、书法、牌匾文字精准还原。</li><li><strong>文字渲染行业顶尖</strong>：海报、LOGO、标语、中英混排文字清晰可辨，不会扭曲、错位，电商或新媒体海报刚需</li><li><strong>人像真实度拉满</strong>：大幅消除 AI 塑料脸，皮肤肌理、发丝、五官比例自然，很少出现畸形手脚，适配写真、模特、人物扩图（半身转全身）</li></ol><p><span style="color:red;">Qwen-Image 模型如果要生成带有中文的图片，需要对在提示词中对中文文字加上引号，例如：&quot;中文图片&quot;。</span></p><blockquote><p>模型文件搭配</p></blockquote><ul><li>CLIP 文本模型：qwen_2.5_vl_7b_fp8_scaled.safetensors</li><li>UNet 扩散模型：qwen_image_2512_fp8_e4m3fn.safetensor。</li><li>VAE编码解码模型：qwen_image_vae.safetensors（专属的VAE模型）。</li></ul><h3 id="中文人物图片" tabindex="-1">中文人物图片 <a class="header-anchor" href="#中文人物图片" aria-label="Permalink to &quot;中文人物图片&quot;">​</a></h3><p><img src="'+c+'" alt="comfyui_2026-08-11_101939_553.png" loading="lazy"></p><h3 id="中文海报" tabindex="-1">中文海报 <a class="header-anchor" href="#中文海报" aria-label="Permalink to &quot;中文海报&quot;">​</a></h3><p>如图是中文海报的工作流示例 <img src="'+u+'" alt="comfyui_2026-08-11_103619_221.png" loading="lazy"></p><h3 id="中文logo" tabindex="-1">中文Logo <a class="header-anchor" href="#中文logo" aria-label="Permalink to &quot;中文Logo&quot;">​</a></h3><p><img src="'+d+'" alt="comfyui_2026-08-11_104436_914.png" loading="lazy"></p><h2 id="qwen-image-edit-图生图工作流" tabindex="-1">Qwen-Image-Edit 图生图工作流 <a class="header-anchor" href="#qwen-image-edit-图生图工作流" aria-label="Permalink to &quot;Qwen-Image-Edit 图生图工作流&quot;">​</a></h2><h3 id="模型介绍-1" tabindex="-1">模型介绍 <a class="header-anchor" href="#模型介绍-1" aria-label="Permalink to &quot;模型介绍&quot;">​</a></h3><p>Qwen-Image-Edit 模型是在 Qwen-Image 模型的基础上，额外做了大量图像编辑专项训练，专门做图生图和图像编辑的衍生专用版。</p><blockquote><p>模型文件搭配</p></blockquote><p>完整使用Qwen-Image-Edit模型需要用到的模型文件如下:</p><ul><li>CLIP 文本模型：qwen_2.5_vl_7b_fp8_scaled.safetensors</li><li>UNet 扩散模型：qwen_image_edit_2509_fp8_e4m3fn.safetensor</li><li>VAE编码解码模型：qwen_image_vae.safetensors 专属的VAE模型,只能用于Qwen-Image模型。</li><li>lora 模型（可选使用）：qwen-image-edit-2509-lightning-4steps-v1.0-bf16.safetensors,该模型是qwen-Image-Edit模型对应的lora加速模型，推荐采样步数是4步,用于加速生成图像。</li></ul><h3 id="qwenimageeditplus节点-适配qwenimageedit模型的条件编码节点" tabindex="-1">QwenImageEditPlus节点（适配QwenImageEdit模型的条件编码节点） <a class="header-anchor" href="#qwenimageeditplus节点-适配qwenimageedit模型的条件编码节点" aria-label="Permalink to &quot;QwenImageEditPlus节点（适配QwenImageEdit模型的条件编码节点）&quot;">​</a></h3><p><img src="'+m+'" alt="comfyui_2026-08-11_122345_695.png" loading="lazy"></p><p>这个节点是专门适配千问通义 Qwen-Image-Edit 模型的条件编码节点，支持同时输入可选图像和文本提示词，并为图像生成或编辑输出条件数据。</p><blockquote><p>输入输出</p></blockquote><ul><li>输入：文本提示词、CLIP模型、图像（可选）、VAE模型（可选）</li><li>输出：包含图像和文本提示词的条件向量编码，用于后续的图像生成。</li></ul><p><span style="color:red;">注意：该节点会把原图通过 VAE 编码器压缩为初始潜在图像，作为初始图生图的基础。后续采样器基于这个初始潜在图像的基础上进行去噪修改，而非从头生成，从而保证生成的图像主体结构不变。</span></p><h3 id="图像编辑添加装饰" tabindex="-1">图像编辑添加装饰 <a class="header-anchor" href="#图像编辑添加装饰" aria-label="Permalink to &quot;图像编辑添加装饰&quot;">​</a></h3><p>如图通过qwen-image-edit模型对原图进行了编辑处理。 <img src="'+e+'" alt="comfyui_2026-08-11_122131_553.png" loading="lazy"></p><blockquote><p>工作流说明</p></blockquote><p><span style="color:red;">注意：图中Unet节点加载的是qwen_image_edit模型文件。而不是qwen_image模型文件。</span></p><h3 id="角色三视图" tabindex="-1">角色三视图 <a class="header-anchor" href="#角色三视图" aria-label="Permalink to &quot;角色三视图&quot;">​</a></h3><p>可以用Qwen-Image-Edit模型来生成角色三视图。</p><p>如图所示工作流 <img src="'+h+'" alt="comfyui_2026-08-12_155808_494.png" loading="lazy"></p><blockquote><p>工作流说明</p></blockquote><ul><li>三视图的图像分辨率建议按照16:9的比例。否则会导致图像变形。图中分辨率是1280x768。</li><li>提示词直接说明&quot;生成XXX的角色三视图，分别是正视图，侧视图，背视图&quot;即可。</li><li>工作流中使用了 Lora加速模型节点 + CFG 归一化节点。这两个节点用于加速图像生成。具体相关介绍请看其他笔记。</li></ul><h3 id="图像人物换衣服" tabindex="-1">图像人物换衣服 <a class="header-anchor" href="#图像人物换衣服" aria-label="Permalink to &quot;图像人物换衣服&quot;">​</a></h3><p><img src="'+g+'" alt="comfyui_2026-08-12_162234_612.png" loading="lazy"></p><p>图片中的加载CLIP节点的设备参数应该是default。</p><h3 id="图像二次元风格转绘" tabindex="-1">图像二次元风格转绘 <a class="header-anchor" href="#图像二次元风格转绘" aria-label="Permalink to &quot;图像二次元风格转绘&quot;">​</a></h3><p>该工作流将真实图像转换为二次元风格的图像。 <img src="'+f+`" alt="comfyui_2026-08-12_163431_997.png" loading="lazy"></p><p>图片中的加载CLIP节点的设备参数应该是default。</p><blockquote><p>提示词说明</p></blockquote><p>下面是二次元精致插画风的提示词</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>### 正面提示词</span></span>
<span class="line"><span>将人物转换为精致的二次元插画风格，保持人物面部特征和身体姿态不变。采用半厚涂画法，细节丰富，光影层次感强，色彩饱和度适中，画面有官方插画的精致完成度，线条干净，质感高级。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 负面提示词</span></span>
<span class="line"><span>画质模糊，线条杂乱，人物变形，五官错位，肢体扭曲，多手指，缺手指，面部崩坏，色彩脏污，噪点多，锯齿边缘，写实感过重，照片质感</span></span></code></pre></div><h3 id="图像真实风格转绘" tabindex="-1">图像真实风格转绘 <a class="header-anchor" href="#图像真实风格转绘" aria-label="Permalink to &quot;图像真实风格转绘&quot;">​</a></h3><p>该工作流将真实图像转换为真实风格的图像。 <img src="`+q+`" alt="comfyui_2026-08-14_111934_258.png" loading="lazy"></p><p>该工作流中使用了图像对比节点。该节点介绍请看其他笔记。</p><blockquote><p>提示词说明</p></blockquote><p>下面是真实风格的提示词</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>### 正面提示词</span></span>
<span class="line"><span>把这张图片处理成高级商业人像摄影，柔和影棚灯光，细腻真实皮肤质感，保留人物原本五官样貌，电影级色调，8k高清，不要改变人物姿态与脸型</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 负面提示词</span></span>
<span class="line"><span>画质模糊，线条杂乱，人物变形，五官错位，肢体扭曲，多手指，缺手指，面部崩坏，色彩脏污，噪点多，锯齿边缘，写实感过重，照片质感</span></span></code></pre></div><h3 id="海贼王通缉令工作流" tabindex="-1">海贼王通缉令工作流 <a class="header-anchor" href="#海贼王通缉令工作流" aria-label="Permalink to &quot;海贼王通缉令工作流&quot;">​</a></h3><p>该工作流的主要功能就是根据输入的图像，先将其重绘为海贼王的风格，再将其添加到海贼王通缉令图像的指定坐标位置。最后生成一个合成后的图像。</p><p>如图是示例工作流。该工作流分为两个部分。</p><ul><li>第一部分：将输入的图像进行重绘，将其转换为海贼王的风格。</li><li>第二部分：将重绘后的图像根据指定坐标位置，添加到海贼王通缉令图像中。先添加图像，然后添加文本。</li></ul><p>第一部分 <img src="`+b+'" alt="comfyui_2026-08-24_103422_254.png" loading="lazy"></p><p>第二部分 <img src="'+y+'" alt="comfyui_2026-08-24_103742_057.png" loading="lazy"></p><p>工作流中用到了文字覆盖节点和合成图像节点。节点介绍请看笔记其他部分。</p><h2 id="qwen3-vl-提示词反推工作流" tabindex="-1">Qwen3-VL 提示词反推工作流 <a class="header-anchor" href="#qwen3-vl-提示词反推工作流" aria-label="Permalink to &quot;Qwen3-VL 提示词反推工作流&quot;">​</a></h2><p>所谓的提示词反推工作流，是指根据输入的图像，视频等媒体文件，通过模型，反推生成对应的文本提示词。</p><blockquote><p>核心原理</p></blockquote><p>提示词反推的核心原理是用具备视觉理解能力的大语言模型（VL模型）读取图片或视频，然后输出通顺的自然语言描述，而非零散关键词。</p><blockquote><p>模型介绍</p></blockquote><p>目前 视觉语言（vlm）模型 Qwen3-VL 的中文理解能力最强，直接输出中文描述，完美适配 Qwen-Image-Edit 等国产模型，支持批量处理。</p><p><a href="https://huggingface.co/Comfy-Org/Qwen3-VL/tree/main/text_encoders" target="_blank" rel="noreferrer">Qwen3-VL 模型下载地址(需外网访问) https://huggingface.co/Comfy-Org/Qwen3-VL/tree/main/text_encoders</a></p><h3 id="示例工作流-2" tabindex="-1">示例工作流 <a class="header-anchor" href="#示例工作流-2" aria-label="Permalink to &quot;示例工作流&quot;">​</a></h3><p>如图是根据一个图片进行提示词反推。图中的CLIP模型是 qwen3vl_8b_fp8_scaled.safetensors 模型。</p><p>该工作流耗时约70秒。因此建议工作流验证阶段不建议使用。等到工作流完全搭建好后，再使用提示词反推。</p><p><img src="'+k+'" alt="comfyui_2026-08-13_173256_832.png" loading="lazy"></p><blockquote><p>工作流说明</p></blockquote><ul><li>图中使用了 PreviewAny 预览任意节点，来预览输入数据的文本表示形式。具体介绍请看其他笔记。</li><li>图中使用了 TextGenerator 节点，来生成文本提示词。具体介绍请看其他笔记。</li></ul><h2 id="wan2-2-文生视频-14b工作流" tabindex="-1">wan2.2 文生视频 14B工作流 <a class="header-anchor" href="#wan2-2-文生视频-14b工作流" aria-label="Permalink to &quot;wan2.2 文生视频 14B工作流&quot;">​</a></h2><p>该工作流采用高低噪声双采样视频生成方案。</p><h3 id="高低噪声双采样视频生成方案说明" tabindex="-1">高低噪声双采样视频生成方案说明 <a class="header-anchor" href="#高低噪声双采样视频生成方案说明" aria-label="Permalink to &quot;高低噪声双采样视频生成方案说明&quot;">​</a></h3><blockquote><p>工作流程说明</p></blockquote><ol><li>先初始化一个充满噪点的视频。什么画面都看不见。</li><li>第一次采样：让高噪声模型对视频噪点进行采样处理。主要任务：把整个视频的框架定下来。人物长什么样、场景是什么、镜头怎么动、物体怎么运动，全部由它决定。最后输出一个视频草稿。</li><li>第二次采样：让低噪声模型再次对视频噪点进行采样处理。主要任务：把视频草稿的画面变清晰，补上皮肤、衣服、环境细节等。最后输出一个清晰的视频。</li></ol><p>相当于用高噪声模型先速写一个视频草稿，再用低噪声模型对视频草稿进行细化，完善视频内容。</p><blockquote><p>采样步数设置说明</p></blockquote><p>官方建议如下：</p><ol><li>视频质量最高时：总采样步数一共为20步。即第一次采样是10步，第二次采样也是10步。</li><li>视频质量中等时：总采样步数一共为16步。即第一次采样是8步，第二次采样也是8步。</li><li>工作流使用了4步LoRA加速模型时：总采样步数一共为4步。即第一次采样是2步，第二次采样也是2步。</li></ol><blockquote><p>优缺点</p></blockquote><p>高低噪声双采样视频生成方案相比其他的视频生成方案：</p><ul><li>优点：视频质量上限更高。视频帧间一致性更好，抑制闪烁、肢体崩坏能力强。</li><li>缺点：硬件门槛高，配置复杂，高低噪声双模型显存开销翻倍。</li></ul><h3 id="使用模型介绍" tabindex="-1">使用模型介绍 <a class="header-anchor" href="#使用模型介绍" aria-label="Permalink to &quot;使用模型介绍&quot;">​</a></h3><ul><li>高噪声文生视频模型：<code>wan2.2_t2v_high_noise_14B_fp8_scaled.safetensors</code></li><li>高噪声文生视频加速4步 LoRA 模型：<code>wan2.2_t2v_lightx2v_4steps_lora_v1.1_high_noise.safetensors</code></li><li>低噪声文生视频模型：<code>wan2.2_t2v_low_noise_14B_fp8_scaled.safetensors</code></li><li>低噪声文生视频加速4步 LoRA 模型：<code>wan2.2_t2v_lightx2v_4steps_lora_v1.1_low_noise.safetensors</code></li><li>CLIP模型：<code>umt5_xxl_fp8_e4m3fn_scaled.safetensors</code> Wan 专属的文本编码器。底层是谷歌的T5 语言模型，用于文本提示词的编码。</li><li>VAE模型：<code>wan_2.1_vae.safetensors</code> Wan 专属视频 VAE 模型。</li></ul><p><span style="color:red;">注意：加速LoRA模型不能交叉混用，高噪声模型只能搭配 高噪声LoRA，低噪声模型只能搭配 低噪声 LoRA，交叉使用直接画面崩坏。</span></p><h3 id="空latent视频-hunyuan-节点" tabindex="-1">空Latent视频（Hunyuan）节点 <a class="header-anchor" href="#空latent视频-hunyuan-节点" aria-label="Permalink to &quot;空Latent视频（Hunyuan）节点&quot;">​</a></h3><p>该节点是可以适配 Wan2.2 和 HunyuanVideo 这两个视频模型的空 Latent 视频节点。</p><p>之所以该节点命名为 Hunyuan，是因为该节点一开始是为 HunyuanVideo 模型设计的。后来 Wan2.2 模型的官方主动做兼容，因此该节点也可以适配 Wan2.2 模型。</p><p><img src="'+w+'" alt="comfyui_2026-08-14_173308_170.png" loading="lazy"></p><blockquote><p>输入输出</p></blockquote><ul><li>宽度/高度：视频的宽度/高度。</li><li>长度：视频的长度。是以帧为单位。</li><li>输出：生成潜在视频样本，用于后续的视频处理和视频生成。</li></ul><p><span style="color:red;">注意：视频长度是以帧为单位。假设视频是5秒，每秒16帧。那么视频长度应该设置为（5 * 16）+ 1 帧，一共81帧。+1是因为需要额外再补一帧空白帧。 </span></p><h3 id="_4步lora加速工作流" tabindex="-1">4步Lora加速工作流 <a class="header-anchor" href="#_4步lora加速工作流" aria-label="Permalink to &quot;4步Lora加速工作流&quot;">​</a></h3><p>如图所示，是高低噪声双采样视频生成方案的工作流。并使用了4步LoRA加速模型。5060ti16G显卡,耗时约130秒。 <img src="'+x+'" alt="comfyui_2026-08-15_161553_927.png" loading="lazy"></p><blockquote><p>工作流注意说明</p></blockquote><ol start="0"><li>图中该视频的分辨率是640x480。如果要更高的分辨率，那么生成时间会增加。</li><li>工作流中使用了K采样器高级节点,并且是通过二次采样的。 <ul><li>第一次采样的采样器的数据会作为第二次采样的输入。因此需要<strong>开启 添加噪波和返回剩余噪波 选项</strong>。</li><li>第二次采样的采样器输入的数据是从第一次采样中获取的。因此需要<strong>关闭 添加噪波和返回剩余噪波 选项</strong>。</li><li><strong>第二次采样器的种子值也需要固定</strong>，不固定会导致两个采样器的种子值不一致。</li></ul></li><li>由于工作流中使用了4步LoRA加速模型，表示总的采样步数一共为4步。即第一次采样是2步，第二次采样也是2步。<strong>因此第一个采样器的开始结束步数为0-2，第二个采样器的开始结束步数为2-4。</strong></li><li>由于工作流中使用了Lora加速模型，因此CFG值相比不使用Lora加速模型的情况下需要调低，具体数值需要经过多次测试。图中的CFG值设置为1 效果好。</li><li>工作流中的创建视频节点设置的是16帧/秒。如果想要生成5秒的视频，那么空Latent视频节点的视频长度应该设置为（5 * 16）+ 1 帧，一共81帧。+1是因为需要额外再补一帧空白帧。这两个节点需要搭配使用。</li><li>加载CLIP模型节点，由于使用的是Wan 专属的文本编码器。因此类型参数需要选择<code>wan</code>。</li></ol><h2 id="wan2-2-图生视频-14b工作流" tabindex="-1">wan2.2 图生视频 14B工作流 <a class="header-anchor" href="#wan2-2-图生视频-14b工作流" aria-label="Permalink to &quot;wan2.2 图生视频 14B工作流&quot;">​</a></h2><p>该工作流采用高低噪声双采样视频生成方案。该工作流是在文生视频工作流的基础上，进行了修改。</p><h3 id="使用模型介绍-1" tabindex="-1">使用模型介绍 <a class="header-anchor" href="#使用模型介绍-1" aria-label="Permalink to &quot;使用模型介绍&quot;">​</a></h3><ul><li>高噪声图生视频模型：<code>wan2.2_i2v_high_noise_14B_fp8_scaled.safetensors</code></li><li>高噪声图生视频加速4步 LoRA 模型：<code>wan2.2_i2v_lightx2v_4steps_lora_v1_high_noise.safetensors</code></li><li>低噪声图生视频模型：<code>wan2.2_i2v_low_noise_14B_fp8_scaled.safetensors</code></li><li>低噪声图生视频加速4步 LoRA 模型：<code>wan2.2_i2v_lightx2v_4steps_lora_v1_low_noise.safetensors</code></li><li>CLIP模型：<code>umt5_xxl_fp8_e4m3fn_scaled.safetensors</code> Wan 专属的文本编码器。底层是谷歌的T5 语言模型，用于文本提示词的编码。</li><li>VAE模型：<code>wan_2.1_vae.safetensors</code> Wan 专属视频 VAE 模型。</li></ul><p><span style="color:red;">注意：加速LoRA模型不能交叉混用，高噪声模型只能搭配 高噪声LoRA，低噪声模型只能搭配 低噪声 LoRA，交叉使用直接画面崩坏。</span></p><h3 id="图像到视频-wan-节点" tabindex="-1">图像到视频(wan) 节点 <a class="header-anchor" href="#图像到视频-wan-节点" aria-label="Permalink to &quot;图像到视频(wan) 节点&quot;">​</a></h3><p><img src="'+C+'" alt="comfyui_2026-08-15_173510_459.png" loading="lazy"></p><p>图像到视频(wan) 节点会为视频生成创建一个空的潜在空间，并可以结合起始图像和 CLIP 视觉输出，以引导视频生成过程。</p><p>该节点会根据提供的图像和视觉数据，将输入正负面提示词进行二次修改。</p><blockquote><p>参数</p></blockquote><ul><li>输入 <ul><li>正负面条件：正负面提示词。</li><li>vae：用于将图像编码到潜在空间的 VAE 模型</li><li>clip视觉输出：可选的CLIP视觉模型对象。可额外引导视频生成。</li><li>开始图像: 可选的起始图像，用于初始化视频生成。</li><li>宽度/高度：视频的宽度/高度。</li><li>长度：视频的长度。是以帧为单位。默认值为81帧。</li></ul></li><li>输出 <ul><li>正负面条件：整合图像和视觉数据的修改后的正负面提示词。</li><li>生成潜在视频样本，用于后续的视频处理和视频生成。</li></ul></li></ul><h3 id="_4步lora加速工作流-1" tabindex="-1">4步Lora加速工作流 <a class="header-anchor" href="#_4步lora加速工作流-1" aria-label="Permalink to &quot;4步Lora加速工作流&quot;">​</a></h3><p>如图工作流。并使用了4步LoRA加速模型。5060ti16G显卡,耗时约220秒。</p><p>可以看到通过图片+提示词，来生成的一个5秒的视频。 <img src="'+I+'" alt="comfyui_2026-08-15_222156_201.png" loading="lazy"></p><blockquote><p>工作流注意说明</p></blockquote><ul><li>工作流中添加了图像到视频(wan) 节点，用于加载图片作为视频的起始帧。</li><li>其他可以参考wan2.2文生视频工作流。</li></ul><h2 id="wan2-2-首尾帧图生视频-14b工作流" tabindex="-1">wan2.2 首尾帧图生视频 14B工作流 <a class="header-anchor" href="#wan2-2-首尾帧图生视频-14b工作流" aria-label="Permalink to &quot;wan2.2 首尾帧图生视频 14B工作流&quot;">​</a></h2><p>该工作流是在图生视频工作流的基础上，添加了首尾帧的图像。用于引导视频生成。</p><h3 id="使用模型介绍-2" tabindex="-1">使用模型介绍 <a class="header-anchor" href="#使用模型介绍-2" aria-label="Permalink to &quot;使用模型介绍&quot;">​</a></h3><p>使用模型参考图生视频工作流。</p><h3 id="wan-首尾帧视频-节点" tabindex="-1">Wan 首尾帧视频 节点 <a class="header-anchor" href="#wan-首尾帧视频-节点" aria-label="Permalink to &quot;Wan 首尾帧视频 节点&quot;">​</a></h3><p><img src="'+P+'" alt="comfyui_2026-08-15_232628_203.png" loading="lazy"></p><p>Wan 首尾帧视频 节点通过结合起始帧、结束帧与文本提示词来创建视频条件。</p><p>它通过编码首帧和末帧、应用遮罩引导生成过程，并在可用时融入 CLIP 视觉特征，为视频生成生成潜在表示。</p><blockquote><p>参数</p></blockquote><ul><li>输入 <ul><li>正负面条件：正负面提示词。</li><li>vae：用于将图像编码到潜在空间的 VAE 模型</li><li>clip视觉起始图像：可选的CLIP视觉模型对象。从起始图像提取的 CLIP 视觉特征</li><li>clip视觉结束图像：可选的CLIP视觉模型对象。从结束图像提取的 CLIP 视觉特征</li><li>起始图像: 可选视频序列的起始帧图像。</li><li>结束图像: 可选视频序列的结束帧图像。</li><li>宽度/高度：视频的宽度/高度。</li><li>长度：视频的长度。是以帧为单位。默认值为81帧。</li></ul></li><li>输出 <ul><li>正负面条件：整合图像和视觉数据的修改后的正负面提示词。</li><li>生成潜在视频样本，用于后续的视频处理和视频生成。</li></ul></li></ul><h3 id="调整尺寸并填充图像-节点" tabindex="-1">调整尺寸并填充图像 节点 <a class="header-anchor" href="#调整尺寸并填充图像-节点" aria-label="Permalink to &quot;调整尺寸并填充图像 节点&quot;">​</a></h3><p><img src="'+L+'" alt="comfyui_2026-08-16_001720_875.png" loading="lazy"></p><p>该节点用于将图像调整至指定尺寸范围内，同时保持原始宽高比。它会按比例缩小图像以适配目标宽度和高度，然后在边缘添加填充以填补剩余空间。</p><p>填充颜色和插值方法可自定义，以控制填充区域的外观和缩放质量。</p><blockquote><p>参数</p></blockquote><ul><li>输入 <ul><li>图像：要调整尺寸的图像。</li><li>宽度/高度：输出图像的宽度/高度。</li><li>填充颜色：用于填充缩放后图像周围区域的背景颜色。默认值为white。</li><li>插值方法：用于调整图像大小的插值方法（默认值：&quot;area&quot;）。</li></ul></li><li>输出 <ul><li>调整大小并填充后的输出图像</li></ul></li></ul><p><span style="color:red;">注意：在通过首尾帧图像生成视频时，需要确保首尾帧图像的宽度/高度一致。否则会导致视频生成异常。</span></p><h3 id="_4步lora加速工作流-2" tabindex="-1">4步Lora加速工作流 <a class="header-anchor" href="#_4步lora加速工作流-2" aria-label="Permalink to &quot;4步Lora加速工作流&quot;">​</a></h3><p>如图工作流。5060ti16G显卡,耗时约210秒。</p><p>可以看到通过图片+提示词，来生成的包含首尾帧的5秒视频。 <img src="'+v+'" alt="comfyui_2026-08-16_001115_341.png" loading="lazy"></p><blockquote><p>工作流注意说明</p></blockquote><ul><li>工作流添加了Wan 首尾帧视频 节点，用于加载首尾帧图像。</li><li>工作流还添加了 调整尺寸并填充图像 节点，用于调整首尾帧图像的尺寸，使它们的宽度/高度一致。否则会导致视频生成异常。</li><li>其他可以参考wan2.2图生视频工作流。</li></ul>',169)])])}const W=o(A,[["render",E]]);export{N as __pageData,W as default};
